package mdm

import (
	"fmt"
	"io"
	"text/template"

	"github.com/meetflowstate/flowstate-telemetry/internal/config"
)

const intuneTemplate = `# Flowstate Telemetry — Microsoft Intune deployment script
# Generated by flowstate-telemetry generate-mdm --format intune
# Deploy via Intune > Devices > Scripts > Add (PowerShell)
#
# KEY: this script embeds ONE Flowstate key. Every user it configures is
# attributed to that key's owner in Flowstate; per-user attribution needs a
# per-user key substituted for $Key below.
#
# The key is never set as OTEL_EXPORTER_OTLP_HEADERS (every OpenTelemetry SDK
# would send it to its own collector): it goes into Claude Code's and VS Code
# Copilot Chat's own settings and the user-scope FLOWSTATE_* variables. Run
# the script as the logged-on user (Intune: "Run this script using the logged
# on credentials: Yes"); it configures that user's profile.
#
# UPGRADING: earlier versions ran as SYSTEM and set FLOWSTATE_OTLP_KEY,
# OTEL_EXPORTER_OTLP_HEADERS and OTEL_RESOURCE_ATTRIBUTES machine-wide, where
# every account and every OpenTelemetry SDK on the device reads them. A
# standard user cannot remove Machine-scope variables, so this script only
# tries (and warns). Deploy the separate machine clean-up script once, as
# SYSTEM, to remove them:
#     flowstate-telemetry generate-mdm --format intune --machine-cleanup

$ErrorActionPreference = "Stop"

$Endpoint = "{{ .Endpoint }}"
$Key = "{{ .Key }}"

Write-Host "Configuring Flowstate Telemetry..."

# Per-user variables (earlier versions set them machine-wide, readable by
# every account on the device)
[System.Environment]::SetEnvironmentVariable("FLOWSTATE_OTLP_ENDPOINT", $Endpoint, "User")
[System.Environment]::SetEnvironmentVariable("FLOWSTATE_OTLP_KEY", $Key, "User")

# Best-effort removal of what earlier versions set machine-wide. Without
# admin rights this fails: warn and carry on configuring the user's tools.
$MachineLeft = @()
function Remove-MachineVariable([string]$Name) {
    try {
        [System.Environment]::SetEnvironmentVariable($Name, $null, "Machine")
    } catch {
        Write-Warning "Could not remove machine-wide $($Name) (needs admin rights): $($_.Exception.Message)"
        $script:MachineLeft += $Name
    }
}
foreach ($name in @("FLOWSTATE_OTLP_ENDPOINT", "FLOWSTATE_OTLP_KEY")) {
    if ([System.Environment]::GetEnvironmentVariable($name, "Machine")) { Remove-MachineVariable $name }
}
# Earlier versions exported the key to every process as OTEL_EXPORTER_OTLP_HEADERS
$headers = [System.Environment]::GetEnvironmentVariable("OTEL_EXPORTER_OTLP_HEADERS", "Machine")
if ($headers -and $headers.Contains("x-flowstate-key")) { Remove-MachineVariable "OTEL_EXPORTER_OTLP_HEADERS" }
# Earlier versions forced service.name for every tool
if ([System.Environment]::GetEnvironmentVariable("OTEL_RESOURCE_ATTRIBUTES", "Machine") -eq "service.name=flowstate-telemetry") { Remove-MachineVariable "OTEL_RESOURCE_ATTRIBUTES" }
$headers = [System.Environment]::GetEnvironmentVariable("OTEL_EXPORTER_OTLP_HEADERS", "User")
if ($headers -and $headers.Contains("x-flowstate-key")) {
    try { [System.Environment]::SetEnvironmentVariable("OTEL_EXPORTER_OTLP_HEADERS", $null, "User") } catch { Write-Warning "Could not remove user OTEL_EXPORTER_OTLP_HEADERS: $($_.Exception.Message)" }
}

# Also set for current user session
$env:FLOWSTATE_OTLP_ENDPOINT = $Endpoint
$env:FLOWSTATE_OTLP_KEY = $Key

# Configure Claude Code
$ClaudeDir = Join-Path $env:USERPROFILE ".claude"
$ClaudeSettings = Join-Path $ClaudeDir "settings.json"

if (-not (Test-Path $ClaudeDir)) {
    New-Item -ItemType Directory -Path $ClaudeDir -Force | Out-Null
}

$envBlock = @{
    "CLAUDE_CODE_ENABLE_TELEMETRY" = "1"
    "OTEL_METRICS_EXPORTER" = "otlp"
    "OTEL_LOGS_EXPORTER" = "otlp"
    "OTEL_EXPORTER_OTLP_PROTOCOL" = "http/protobuf"
    "OTEL_EXPORTER_OTLP_ENDPOINT" = $Endpoint
    "OTEL_EXPORTER_OTLP_HEADERS" = "x-flowstate-key=$Key"
    "OTEL_EXPORTER_OTLP_METRICS_TEMPORALITY_PREFERENCE" = "delta"
    "OTEL_METRICS_INCLUDE_SESSION_ID" = "true"
    "OTEL_METRICS_INCLUDE_ACCOUNT_UUID" = "true"
}

if (Test-Path $ClaudeSettings) {
    $settings = Get-Content $ClaudeSettings -Raw | ConvertFrom-Json
    if (-not $settings.env) {
        $settings | Add-Member -NotePropertyName "env" -NotePropertyValue @{}
    }
    $settings.env.PSObject.Properties.Remove("OTEL_METRICS_TEMPORALITY_PREFERENCE")
    foreach ($kv in $envBlock.GetEnumerator()) {
        $settings.env | Add-Member -NotePropertyName $kv.Key -NotePropertyValue $kv.Value -Force
    }
} else {
    $settings = @{ "env" = $envBlock }
}

$settings | ConvertTo-Json -Depth 10 | Set-Content $ClaudeSettings -Encoding UTF8

# Configure VS Code Copilot Chat
$VSCodeSettings = Join-Path $env:APPDATA "Code\User\settings.json"
if (Test-Path $VSCodeSettings) {
    $vsSettings = Get-Content $VSCodeSettings -Raw | ConvertFrom-Json
    $vsSettings | Add-Member -NotePropertyName "github.copilot.chat.otel.enabled" -NotePropertyValue $true -Force
    $vsSettings | Add-Member -NotePropertyName "github.copilot.chat.otel.exporterType" -NotePropertyValue "otlp-http" -Force
    $vsSettings | Add-Member -NotePropertyName "github.copilot.chat.otel.otlpEndpoint" -NotePropertyValue $Endpoint -Force
    $vsSettings | Add-Member -NotePropertyName "github.copilot.chat.otel.headers" -NotePropertyValue @{ "x-flowstate-key" = $Key } -Force
    # Keep the key out of VS Code Settings Sync
    $ignored = @()
    if ($vsSettings.PSObject.Properties.Name -contains "settingsSync.ignoredSettings") { $ignored = @($vsSettings."settingsSync.ignoredSettings") }
    if ($ignored -notcontains "github.copilot.chat.otel.headers") { $ignored += "github.copilot.chat.otel.headers" }
    $vsSettings | Add-Member -NotePropertyName "settingsSync.ignoredSettings" -NotePropertyValue $ignored -Force
    $vsSettings | ConvertTo-Json -Depth 10 | Set-Content $VSCodeSettings -Encoding UTF8
    Write-Host "  Configured: VS Code Copilot Chat"
}

if ($MachineLeft.Count -gt 0) {
    Write-Warning ("Machine-wide " + ($MachineLeft -join ", ") + " from an earlier version are still set for every account and app on this device. Deploy the machine clean-up script (flowstate-telemetry generate-mdm --format intune --machine-cleanup) as SYSTEM.")
}

Write-Host "Flowstate telemetry configuration complete."
exit 0
`

const intuneMachineCleanupTemplate = `# Flowstate Telemetry — Microsoft Intune machine-wide clean-up script
# Generated by flowstate-telemetry generate-mdm --format intune --machine-cleanup
# Deploy via Intune > Devices > Scripts > Add (PowerShell) with "Run this
# script using the logged on credentials: No" (it runs as SYSTEM).
#
# Earlier versions of the Flowstate deployment script set FLOWSTATE_OTLP_KEY,
# OTEL_EXPORTER_OTLP_HEADERS (carrying the key) and OTEL_RESOURCE_ATTRIBUTES
# machine-wide, where every account and every OpenTelemetry SDK on the device
# reads them. The current per-user script cannot remove Machine-scope
# variables without admin rights; this script does. It embeds no key and
# removes only values Flowstate wrote: an OTEL_EXPORTER_OTLP_HEADERS without
# x-flowstate-key, or other OTEL_RESOURCE_ATTRIBUTES, are left alone.

$ErrorActionPreference = "Stop"

$principal = New-Object Security.Principal.WindowsPrincipal([Security.Principal.WindowsIdentity]::GetCurrent())
if (-not $principal.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)) {
    Write-Error "Run this script as SYSTEM or an administrator: Machine-scope variables cannot be changed otherwise."
    exit 1
}

$failed = $false
function Remove-MachineVariable([string]$Name) {
    try {
        [System.Environment]::SetEnvironmentVariable($Name, $null, "Machine")
        Write-Host "  Removed machine-wide $Name"
    } catch {
        Write-Warning "Could not remove machine-wide $($Name): $($_.Exception.Message)"
        $script:failed = $true
    }
}

foreach ($name in @("FLOWSTATE_OTLP_ENDPOINT", "FLOWSTATE_OTLP_KEY")) {
    if ([System.Environment]::GetEnvironmentVariable($name, "Machine")) { Remove-MachineVariable $name }
}
$headers = [System.Environment]::GetEnvironmentVariable("OTEL_EXPORTER_OTLP_HEADERS", "Machine")
if ($headers -and $headers.Contains("x-flowstate-key")) { Remove-MachineVariable "OTEL_EXPORTER_OTLP_HEADERS" }
if ([System.Environment]::GetEnvironmentVariable("OTEL_RESOURCE_ATTRIBUTES", "Machine") -eq "service.name=flowstate-telemetry") { Remove-MachineVariable "OTEL_RESOURCE_ATTRIBUTES" }

if ($failed) { exit 1 }
Write-Host "Flowstate machine-wide clean-up complete."
exit 0
`

// GenerateIntuneMachineCleanup writes a PowerShell script, to run once as
// SYSTEM, that removes the machine-wide variables earlier Intune scripts set.
// It embeds no key.
func GenerateIntuneMachineCleanup(w io.Writer) error {
	_, err := io.WriteString(w, intuneMachineCleanupTemplate)
	return err
}

// GenerateIntune writes a PowerShell script for Microsoft Intune deployment.
// It runs as the logged-on user; see GenerateIntuneMachineCleanup for the
// machine-wide clean-up that needs admin rights.
func GenerateIntune(w io.Writer, cfg config.Config) error {
	tmpl, err := template.New("intune").Parse(intuneTemplate)
	if err != nil {
		return fmt.Errorf("parsing template: %w", err)
	}

	return tmpl.Execute(w, map[string]string{
		"Endpoint": cfg.Endpoint,
		"Key":      cfg.Key,
	})
}
